function snakeTick(dt){snakeClock+=dt;if(bonus){bonus.ttl-=dt;if(bonus.ttl<=0)bonus=null}const interval=.30-(snakeSpeed-1)*.027;while(snakeClock>=interval&&state==='play'){snakeClock-=interval;if(turns.length)direction=turns.shift();const p={x:(snake[0].x+direction.x+cols)%cols,y:(snake[0].y+direction.y+rows)%rows};const eat=food&&same(p,food),extra=bonus&&same(p,bonus),grow=eat||extra;const body=grow?snake:snake.slice(0,-1);if(walls.some(w=>same(w,p))||body.some(w=>same(w,p))){snakeSave();state='over';beep(110,.25);break}snake.unshift(p);if(!grow)snake.pop();if(eat){snakeScore+=snakeSpeed*10;foodCount++;food=null;food=freeCell();if(foodCount%5===0){bonus=freeCell();if(bonus)bonus.ttl=6}beep(800,.06)}if(extra){snakeScore+=snakeSpeed*50;bonus=null;beep(1100,.1)}if(!food){snakeSave();state='win'}}}
function menuRows(title,items,index){text(title,96,15,13,'center');rect(0,20,192,1);items.forEach((v,i)=>{const y=29+i*18;if(i===index){rect(7,y,178,17);c.fillStyle=paper}else c.fillStyle=ink;c.textAlign='center';c.font='bold 10px monospace';c.fillText(v,96,y+12)});text('Select',96,125,9,'center')}
function action(k){if(k==='power'){const off=state==='off';impactAction(k);if(off)state='games';return}if(state==='off')return;if(k==='0'){sound=!sound;beep();return}if(state==='games'){if(['2','up','8','down'].includes(k))gameChoice=1-gameChoice;if(['5','ok'].includes(k)){game=gameChoice===0?'impact':'snake';state=game==='impact'?'menu':'snake-menu';selection=0;snakeChoice=0;held.clear()}return}if(game==='impact'){if(state==='menu'&&k==='back'){state='games';held.clear();return}impactAction(k);return}if(state==='snake-menu'){if(['2','up'].includes(k))snakeChoice=(snakeChoice+3)%4;if(['8','down'].includes(k))snakeChoice=(snakeChoice+1)%4;if(k==='back'){state='games';return}const choose=['ok','5'].includes(k),right=['6','right'].includes(k),left=['4','left'].includes(k);if(choose&&snakeChoice===0)snakeStart();if(snakeChoice===1&&(choose||left||right))snakeSpeed=(snakeSpeed-1+(left?8:1))%9+1;if(snakeChoice===2&&(choose||left||right))maze=(maze+(left?5:1))%6;if(choose&&snakeChoice===3)state='help';return}if(state==='help'){if(['ok','5','back'].includes(k))state='snake-menu';return}if(state==='pause'){if(['ok','5','hash'].includes(k))state='play';if(k==='back'){snakeSave();state='snake-menu'}return}if(state==='over'||state==='win'){if(['ok','5'].includes(k))snakeStart();if(k==='back')state='snake-menu';return}if(state==='play'){if(['ok','5','hash','back'].includes(k)){state='pause';held.clear()}else snakeTurn(k)}}
function update(dt){if(game==='snake'){if(state==='play')snakeTick(dt)}else impactUpdate(dt)}
function draw(){if(state==='games'){c.fillStyle=paper;c.fillRect(0,0,W,H);menuRows('NOKIA · GAMES',['Space Impact +','Snake II'],gameChoice);text('2 / 8 to browse',96,91,9,'center');return}if(game==='impact'){impactDraw();return}c.fillStyle=paper;c.fillRect(0,0,W,H);if(state==='off')return;if(state==='snake-menu'){menuRows('SNAKE II',['New game','Speed: '+snakeSpeed+' / 9','Maze: '+(maze===0?'No maze':maze),'How to play'],snakeChoice);text('BEST '+snakeBest,96,112,8,'center');text('C: Games',4,125,8);return}if(state==='help'){text('SNAKE II',96,14,12,'center');['2 / 8   Up / Down','4 / 6   Left / Right','Eat food to grow','Avoid your tail & walls','Edges wrap to other side','5 / # / C: pause','0: sound   C: back'].forEach((s,i)=>text(s,5,31+i*12,9));return}text('SCORE '+snakeScore,3,11,9);text('BEST '+snakeBest,189,11,9,'right');rect(0,15,192,1);walls.forEach(p=>rect(p.x*cell,p.y*cell+18,6,6));snake.forEach((p,i)=>{rect(p.x*cell,p.y*cell+18,5,5);if(i===0){c.fillStyle=paper;c.fillRect(p.x*cell+2,p.y*cell+20,1,1)}});if(food){rect(food.x*cell+1,food.y*cell+19,4,4)}if(bonus){c.strokeStyle=ink;c.strokeRect(bonus.x*cell+.5,bonus.y*cell+18.5,5,5)}if(state==='pause')panel('PAUSED','5 / Select: resume','C: Snake menu');if(state==='over')panel('GAME OVER','Score '+snakeScore+' Best '+snakeBest,'5: retry  C: menu');if(state==='win')panel('WELL PLAYED!','You filled the board','5: retry  C: menu')}

function frame(now){const dt=Math.min(.035,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
const pointerKeys=new Map();document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const k=b.dataset.key;pointerKeys.set(e.pointerId,k);b.classList.add('pressed');const was=state;action(k);if(was==='play'&&state==='play')held.add(k);});function release(e){const k=pointerKeys.get(e.pointerId);pointerKeys.delete(e.pointerId);if(![...pointerKeys.values()].includes(k))held.delete(k);b.classList.remove('pressed')}b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release)});
const keyMap={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',' ':'5',Enter:'ok',Escape:'back',x:'star',X:'star','*':'star','#':'hash',p:'hash',m:'0'};window.addEventListener('keydown',e=>{const k=keyMap[e.key]||(/^[0-9]$/.test(e.key)?e.key:null);if(!k)return;e.preventDefault();if(!e.repeat){const was=state;action(k);if(was==='play'&&state==='play')held.add(k)}});window.addEventListener('keyup',e=>held.delete(keyMap[e.key]||e.key));function pauseHidden(){held.clear();pointerKeys.clear();document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));if(state==='play'){pausedFrom='play';state='pause'}}window.addEventListener('blur',pauseHidden);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseHidden()});document.querySelector('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}});
